definition.script:
pipeline {
    agent none
    stages {
        stage('Parallel Stage') {
            failFast true
            parallel {
                stage('Back-end') {
                    agent {
                        docker { image 'maven:3.9.16-eclipse-temurin-25-noble' }
                    }
                    steps {
                        sh 'mvn --version'
                    }
                }
                stage('Front-end') {
                    agent {
                        docker { image 'node:24-alpine' }
                    }
                    steps {
                        sh 'node --version'
                    }
                }
            }
        }
    }
}
